PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS app_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS controllers (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, area TEXT NOT NULL DEFAULT 'Body Shop', description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP) STRICT;
CREATE TABLE IF NOT EXISTS status_items (id INTEGER PRIMARY KEY, controller_id INTEGER NOT NULL REFERENCES controllers(id) ON DELETE CASCADE, test_id TEXT NOT NULL UNIQUE, station TEXT NOT NULL, function_detail TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'General', milestone TEXT NOT NULL DEFAULT '', criticality TEXT NOT NULL DEFAULT 'Medium', responsible TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Not started', checked_by TEXT NOT NULL DEFAULT '', checked_on TEXT, environment TEXT NOT NULL DEFAULT 'Factory', current_note TEXT NOT NULL DEFAULT '', evidence_link TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP) STRICT;
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY, controller_id INTEGER NOT NULL REFERENCES controllers(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', station TEXT NOT NULL DEFAULT '', priority TEXT NOT NULL DEFAULT 'Medium', owner TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'To do', due_date TEXT, linked_test_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP) STRICT;
CREATE TABLE IF NOT EXISTS open_points (id INTEGER PRIMARY KEY, controller_id INTEGER NOT NULL REFERENCES controllers(id) ON DELETE CASCADE, issue_id TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', impact TEXT NOT NULL DEFAULT '', priority TEXT NOT NULL DEFAULT 'Medium', owner TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Open', waiting_for TEXT NOT NULL DEFAULT '', next_action TEXT NOT NULL DEFAULT '', due_date TEXT, linked_test_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP) STRICT;
CREATE TABLE IF NOT EXISTS daily_notes (id INTEGER PRIMARY KEY, controller_id INTEGER REFERENCES controllers(id) ON DELETE SET NULL, note_date TEXT NOT NULL, shift TEXT NOT NULL DEFAULT 'Dzień', author TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'Postęp', content TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP) STRICT;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('admin','moderator','user')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP) STRICT;
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, sort_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE IF NOT EXISTS subcategories (id INTEGER PRIMARY KEY, category_id INTEGER NOT NULL REFERENCES categories(id) ON DELETE CASCADE, name TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, UNIQUE(category_id,name)) STRICT;
CREATE TABLE IF NOT EXISTS options (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, value TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, UNIQUE(kind,value)) STRICT;
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS task_checklist (id INTEGER PRIMARY KEY, task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, text TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE IF NOT EXISTS goals (id INTEGER PRIMARY KEY, controller_id INTEGER REFERENCES controllers(id) ON DELETE SET NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Open', due_date TEXT, created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP) STRICT;
CREATE TABLE IF NOT EXISTS goal_links (id INTEGER PRIMARY KEY, goal_id INTEGER NOT NULL REFERENCES goals(id) ON DELETE CASCADE, entity_type TEXT NOT NULL CHECK(entity_type IN ('status','task','point')), entity_id INTEGER NOT NULL, UNIQUE(goal_id,entity_type,entity_id)) STRICT;
CREATE INDEX IF NOT EXISTS idx_status_controller_status ON status_items(controller_id,status);
CREATE INDEX IF NOT EXISTS idx_tasks_controller_status ON tasks(controller_id,status);
CREATE INDEX IF NOT EXISTS idx_points_controller_status ON open_points(controller_id,status);
CREATE INDEX IF NOT EXISTS idx_notes_controller_date ON daily_notes(controller_id,note_date DESC);
INSERT OR REPLACE INTO app_meta(key,value) VALUES('schema_version','2');
